"""Fresh-process consumer of installed packages and an explicit staged harness."""

import argparse
from hashlib import sha256
import importlib.resources
import importlib.util
from importlib.metadata import distribution
import json
from pathlib import Path
import sys
import sysconfig


def digest(path):
    return sha256(Path(path).read_bytes()).hexdigest()


def inventory(directory):
    """Include resources, not just Python; generated bytecode is not source."""
    directory = Path(directory)
    result = {}
    for path in sorted(directory.rglob("*")):
        if "__pycache__" in path.parts or path.suffix in {".pyc", ".pyo"}:
            continue
        if path.is_symlink():
            raise ValueError("symlink in package/fixture inventory")
        if path.is_file():
            result[path.relative_to(directory).as_posix()] = digest(path)
    return result


def check_loaded(roots, inventories):
    loaded = {}
    for name, module in tuple(sys.modules.items()):
        package = name.split(".", 1)[0]
        if package not in roots or module is None:
            continue
        root = roots[package]
        origin = getattr(module, "__file__", None)
        if not origin:
            raise ValueError(f"missing actual module origin: {name}")
        path = Path(origin).resolve()
        if not path.is_relative_to(root):
            raise ValueError(f"checkout/external loaded module: {name}")
        relative = path.relative_to(root).as_posix()
        if relative not in inventories[package] or digest(path) != inventories[package][relative]:
            raise ValueError(f"loaded module differs from exact artifact: {name}")
        spec = getattr(module, "__spec__", None)
        if spec is None or not spec.origin or Path(spec.origin).resolve() != path:
            raise ValueError(f"module spec differs from loaded origin: {name}")
        for entry in getattr(module, "__path__", ()):
            if Path(entry).resolve() != path.parent:
                raise ValueError(f"external package search path: {name}")
        loaded[name] = str(path)
    return loaded


def identity(manifest, kind, *, required=()):
    import quantbt
    import _quantbt_native as native
    import _quantbt_native._quantbt_native as extension

    prefix = Path(sys.prefix).resolve()
    expected_prefix = Path(manifest["prefixes"][kind]).resolve()
    if prefix != expected_prefix or prefix == Path(sys.base_prefix).resolve():
        raise ValueError("consumer is not the exact isolated artifact environment")
    lane = "cp" + "".join(map(str, sys.version_info[:2]))
    if lane != manifest["interpreter"] or not sys.flags.isolated:
        raise ValueError("wrong interpreter or non-isolated consumer")
    sites = {Path(sysconfig.get_path(key)).resolve() for key in ("purelib", "platlib")}
    roots = {"quantbt": Path(quantbt.__file__).resolve().parent,
             "_quantbt_native": Path(native.__file__).resolve().parent}
    inventories = {"quantbt": manifest["core_inventory"],
                   "_quantbt_native": manifest["native_inventory"]}
    for package, root in roots.items():
        if (root.parent not in sites or "site-packages" not in root.parts
                or not root.is_relative_to(prefix) or root != root.parent / package):
            raise ValueError("package outside exact installed site-packages")
        if inventory(root) != inventories[package]:
            raise ValueError("installed package source/resources differ from exact archives")
    for name, package, actual, expected in (
        ("quantbt-engine", "quantbt", quantbt.__version__, manifest["core"]),
        ("quantbt-native", "_quantbt_native", native.version(), manifest["native"]),
    ):
        dist = distribution(name)
        if (dist.version != expected or actual != expected
                or Path(dist.locate_file(package)).resolve() != roots[package]):
            raise ValueError("installed metadata/runtime identity mismatch")
    binary = Path(extension.__file__).resolve()
    if digest(binary) != manifest["native_extension_sha256"]:
        raise ValueError("actually loaded native binary differs from wheel")
    resources = {name: expected for name, expected in manifest["core_inventory"].items()
                 if not name.endswith(".py")}
    if "py.typed" not in resources:
        raise ValueError("required installed typing resource missing")
    for name, expected in resources.items():
        actual = importlib.resources.files("quantbt").joinpath(name).read_bytes()
        if sha256(actual).hexdigest() != expected:
            raise ValueError("installed resource API bytes mismatch")
    loaded = check_loaded(roots, inventories)
    if not set(required).issubset(loaded):
        raise ValueError("requested feature module was never loaded")
    return dict(core=quantbt.__version__, native=native.version(), prefix=str(prefix),
        interpreter=lane, core_origin=str(roots["quantbt"]), native_origin=str(binary),
        native_sha256=digest(binary), resources=resources, loaded_modules=loaded,
        core_files=len(inventories["quantbt"]), native_files=len(inventories["_quantbt_native"]))


class Outcomes:
    def __init__(self, execution_case, execution_property):
        self.collected = []
        self.reports = {}
        self.execution = None
        self.execution_case = execution_case
        self.execution_property = execution_property

    def pytest_collection_finish(self, session):
        self.collected = [item.nodeid for item in session.items]

    def pytest_runtest_logreport(self, report):
        phases = self.reports.setdefault(report.nodeid, {})
        if report.when in phases:
            raise ValueError("repeated test execution cannot renew a proof")
        phases[report.when] = "xfail" if hasattr(report, "wasxfail") else report.outcome
        if report.when == "call":
            values = [value for key, value in report.user_properties if key == self.execution_property]
            if values:
                if report.nodeid != self.execution_case or len(values) != 1 or self.execution is not None:
                    raise ValueError("bounded summary outside its one exact execution case")
                self.execution = json.loads(values[0])


def fixtures_unchanged(manifest, stage):
    actual = {name: digest(stage / name) for name in manifest["fixtures"]}
    if actual != manifest["fixtures"]:
        raise ValueError("staged synthetic harness changed")


def fixture_origins(manifest, stage, required):
    result = {}
    for name, relative in required.items():
        module = sys.modules.get(name)
        origin = getattr(module, "__file__", None)
        expected = stage / relative
        if not origin or Path(origin).resolve() != expected or digest(expected) != manifest["fixtures"][relative]:
            raise ValueError("public fixture was not loaded from the exact external staging")
        result[name] = str(expected)
    return result


def consume(args):
    request_hash = digest(args.manifest)
    manifest = json.loads(args.manifest.read_text())
    stage = Path(__file__).resolve().parents[1]
    checkout = Path(manifest["checkout"]).resolve()
    if (manifest["schema"] != "m5-12-installed-request-v1"
            or stage != Path(manifest["stages"][args.kind]).resolve()
            or stage.is_relative_to(checkout) or Path.cwd().resolve().is_relative_to(checkout)
            or args.output.exists() or args.output.with_suffix(".xml").exists()):
        raise ValueError("fresh outside-checkout harness/output required")
    if sys.pycache_prefix != str(stage.parent / "bytecode"):
        raise ValueError("fresh bytecode location required; do not consume stale installed pyc")
    if any(Path(p).resolve().is_relative_to(checkout / "src") for p in sys.path):
        raise ValueError("checkout source in isolated import path")
    fixtures_unchanged(manifest, stage)
    before = identity(manifest, args.kind)
    # -I removes the script directory too. Only the hashed, staged fixture tree
    # is added; it contains no quantbt package and no checkout bootstrap.
    sys.path.insert(0, str(stage / "tools"))
    sys.path.append(str(stage))
    from m5_12_consumer_matrix import (
        EXECUTION_CASE, EXECUTION_PROPERTY, FEATURES, REQUIRED_FIXTURE_MODULES, REQUIRED_MODULES, execution_bytes,
        selectors, validate_execution, validate_outcomes,
    )
    from m5_12_consumer_budget import OptimizerBudget
    if manifest["features"] != FEATURES:
        raise ValueError("manifest feature roster differs from maintained harness")
    import pytest
    import optuna
    from quantbt.walkforward import WalkForwardEngine

    spec = importlib.util.spec_from_file_location("m512_option_fixtures", stage / "tests/options/conftest.py")
    option_fixtures = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = option_fixtures
    spec.loader.exec_module(option_fixtures)
    outcomes = Outcomes(EXECUTION_CASE, EXECUTION_PROPERTY)
    budget = OptimizerBudget(EXECUTION_CASE)
    with budget.protect(optuna, WalkForwardEngine):
        code = pytest.main(["-q", "--tb=short", "-c", "/dev/null", "--noconftest",
            "--rootdir", str(stage), "--import-mode=prepend",
            "--basetemp", str(stage.parent / "pytest-scratch"),
            "--junitxml", str(args.output.with_suffix(".xml")),
            *[str(stage / node) for node in selectors()]], plugins=[outcomes, option_fixtures, budget])
    if code:
        raise ValueError("installed feature failure or forbidden optimizer invocation")
    features = validate_outcomes(outcomes.collected, outcomes.reports)
    optimizer = budget.receipt()
    validate_execution(outcomes.execution, optimizer)
    fixture_modules = fixture_origins(manifest, stage, REQUIRED_FIXTURE_MODULES)
    after = identity(manifest, args.kind, required=REQUIRED_MODULES)
    if any(before[key] != after[key] for key in before if key != "loaded_modules"):
        raise ValueError("installed identity changed during execution")
    fixtures_unchanged(manifest, stage)
    if digest(args.manifest) != request_hash:
        raise ValueError("consumer request changed during execution")
    execution_output = args.output.with_name(args.kind + "-execution.json")
    with execution_output.open("xb") as stream:
        stream.write(execution_bytes(outcomes.execution))
    result = dict(schema="m5-12-installed-consumer-v1", kind=args.kind, run_id=manifest["run_id"],
        source_commit=manifest["source"]["current_commit"],
        source_provenance_sha256=sha256(json.dumps(manifest["source"], sort_keys=True, allow_nan=False).encode()).hexdigest(),
        fixture_modules=fixture_modules,
        manifest_sha256=request_hash, identity=after, features=features,
        collected=outcomes.collected, reports=outcomes.reports, cwd=str(Path.cwd().resolve()),
        harness=str(stage), skipped=0, optimizer=optimizer, execution=outcomes.execution,
        execution_sha256=digest(execution_output), publication=False,
        empirical_promotion=False, defaults_activated=False)
    with args.output.open("x") as stream:
        json.dump(result, stream, indent=2, sort_keys=True)
        stream.write("\n")
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--kind", choices=("pair", "sdist"), required=True)
    parser.add_argument("--output", type=Path, required=True)
    result = consume(parser.parse_args())
    print(json.dumps(dict(kind=result["kind"], features=result["features"], run_id=result["run_id"])))
